const express = require('express');
const speakeasy = require('speakeasy');
const { DeviceTrustStore } = require('../services/deviceStore');

const app = express();
app.use(express.json());

app.post('/api/devices/trust-mfa', async (req, res) => {
  if (!req.user || !req.user.accountId) {
    return res.status(401).json({ error: 'Authentication required' });
  }

  const { accountId, deviceFingerprint, mfaToken } = req.body;

  if (!accountId || !deviceFingerprint || !mfaToken) {
    return res.status(400).json({ error: 'accountId, deviceFingerprint, and mfaToken are required' });
  }

  // Enforce that caller can only register trusted devices on their own account
  if (req.user.accountId !== accountId) {
    return res.status(403).json({ error: 'Access denied: cannot register trusted devices for another account' });
  }

  const account = await DeviceTrustStore.getAccount(accountId);
  if (!account || !account.mfaSecret) {
    return res.status(404).json({ error: 'Account not found' });
  }

  const isTokenValid = speakeasy.totp.verify({
    secret: account.mfaSecret,
    encoding: 'base32',
    token: mfaToken,
    window: 1
  });

  if (!isTokenValid) {
    return res.status(401).json({ error: 'MFA token validation failed' });
  }

  await DeviceTrustStore.addTrustedDevice(accountId, deviceFingerprint);

  res.json({ success: true, message: 'Device registered as trusted', accountId });
});

app.listen(6007);
